INSERT INTO feature VALUES('content-checkpoints','incremental','Content-addressed checkpoints','incremental-checking','implemented','notable',NULL,'Checked answers persist as checkpoints addressed by content and are restored only when validated; a session over a store that keeps nothing, as each language-server document''s is, neither encodes its checkpoints nor commits its kernel checkpoint, and resumes alike. A located program persists alike: a world''s row, a stated entry and the world formers are content, and an item''s support records the home and the spending of each declaration it reads and the entry the host''s grant resolves for it, so a changed home or grant judges again exactly the items it reaches.','core-incremental surface-session surface-dispatcher','crates/core-incremental/tests/incremental.rs crates/core-incremental/tests/worlds.rs crates/surface-session/tests/checkpoint.rs crates/surface-dispatcher/tests/corpus.rs',NULL,NULL);
